def feature(s):
    sites = s.get('sites', ())
    props = s.get('element_properties', {})
    volume = s.get('lattice', {}).get('volume_A3')
    if volume is None or not math.isfinite(volume) or volume <= 0.0:
        return 0.0
    total = 0.0
    for site in sites:
        radius = props.get(site.get('element', ''), {}).get('covalent_radius_A')
        occupancy = max(0.0, float(site.get('occupancy', 1.0) or 0.0))
        if radius is not None and math.isfinite(radius) and radius > 0.0:
            total += occupancy * radius ** 3
    return float(4.0 * math.pi * total / (3.0 * volume))

def feature(s):
    volume = s.get('lattice', {}).get('volume_A3')
    if volume is None or not math.isfinite(volume) or volume <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    for site in s.get('sites', ()):
        value = props.get(site.get('element', ''), {}).get('valence_electrons')
        occupancy = max(0.0, float(site.get('occupancy', 1.0) or 0.0))
        if value is not None and math.isfinite(value) and value >= 0.0:
            total += occupancy * value
    return float(total / volume)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf for i in range(n)]
    for edge in s.get('neighbors', ()):
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0.0 and occ[j] > 0.0 and d is not None and math.isfinite(d) and d > 0.0:
            nearest[i] = min(nearest[i], d)
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0.0:
        return 0.0
    return float(sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    props = s.get('element_properties', {})
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    en = [props.get(t.get('element', ''), {}).get('eneg') for t in sites]
    count = sum(occ)
    if count <= 0.0:
        return 0.0
    nearest = [math.inf for i in range(n)]
    edges = s.get('neighbors', ())
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0.0 and occ[j] > 0.0 and d is not None and math.isfinite(d) and d > 0.0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0.0 and occ[j] > 0.0 and math.isfinite(nearest[i]) and d is not None and math.isfinite(d) and 0.0 < d <= 1.25 * nearest[i]:
            if en[i] is not None and en[j] is not None and math.isfinite(en[i]) and math.isfinite(en[j]):
                total += occ[i] * occ[j] * (en[i] - en[j]) ** 2 / d
    return float(total / (2.0 * count))
